import { createId } from "./ids";
import { countConsecutiveFailuresByMonitor } from "./notification-dispatcher";
import type {
  CheckResult,
  Incident,
  IncidentStatus,
  Maintenance,
  StatusEvent,
  StatusPageConfig,
} from "./types";

const recoveryStabilityMs = 5 * 60 * 1000;
const activeIncidentStatuses: IncidentStatus[] = [
  "investigating",
  "identified",
  "monitoring",
];

/**
 * Opens and progresses incidents generated by monitor results.
 *
 * Check history is the source of truth for the failure threshold, while the
 * timeline's monitoring timestamp is the durable recovery-stability timer.
 */
export async function reconcileAutomaticIncidents(
  config: StatusPageConfig,
  results: CheckResult[],
  now = new Date(),
): Promise<StatusEvent[]> {
  if (!config.incidents.enabled || results.length === 0) return [];

  const events: StatusEvent[] = [];

  const [activeIncidents, maintenance] = await Promise.all([
    config.database.listIncidents({ status: activeIncidentStatuses }),
    config.maintenance.enabled ? config.database.listUpcoming(now) : [],
  ]);
  // Counted once for the batch rather than once per failing monitor, which
  // used to read the whole history again for each of them.
  const failures = await countConsecutiveFailuresByMonitor(
    config,
    results
      .filter(
        (result) =>
          !result.status &&
          !isCoveredByActiveMaintenance(maintenance, result.name),
      )
      .map((result) => result.name),
    now,
  );

  for (const result of results) {
    if (isCoveredByActiveMaintenance(maintenance, result.name)) continue;

    const related = activeIncidents.filter(
      (incident) =>
        incident.auto &&
        incident.status !== "resolved" &&
        affectsMonitor(incident, result.name),
    );

    if (result.status) {
      await progressRecovery(config, related, result, now, events);
      continue;
    }

    const consecutiveFailures = failures.get(result.name) ?? 0;
    if (
      related.length === 0 &&
      consecutiveFailures >= config.notifications.failureThreshold
    ) {
      const created = await config.database.createIncident({
        title: `${result.name} is unavailable`,
        severity: "major",
        affectedMonitors: [result.name],
        message: result.message || "The monitor is failing. Investigating.",
        status: "investigating",
        auto: true,
      });
      activeIncidents.push(created);
      events.push({
        type: "incident.created",
        occurredAt: now,
        incident: created,
      });
      continue;
    }

    // A failure while the recovery period is running restarts investigation so
    // a following successful check cannot resolve the incident prematurely.
    for (const incident of related.filter(
      (candidate) => candidate.status === "monitoring",
    )) {
      const updated = await config.database.updateIncident(incident.id, {
        id: createId("upd"),
        status: "investigating",
        message: `${result.name} is failing again. Continuing investigation.`,
        createdAt: now,
      });
      replaceIncident(activeIncidents, updated);
      events.push({
        type: "incident.updated",
        occurredAt: now,
        incident: updated,
      });
    }
  }

  return events;
}

async function progressRecovery(
  config: StatusPageConfig,
  incidents: Incident[],
  result: CheckResult,
  now: Date,
  events: StatusEvent[],
): Promise<void> {
  for (const incident of incidents) {
    if (incident.status !== "monitoring") {
      const updated = await config.database.updateIncident(incident.id, {
        id: createId("upd"),
        status: "monitoring",
        message: `${result.name} has recovered. Monitoring stability.`,
        createdAt: now,
      });
      events.push({
        type: "incident.updated",
        occurredAt: now,
        incident: updated,
      });
      continue;
    }

    const monitoringStartedAt = latestUpdateAt(incident, "monitoring");
    if (
      monitoringStartedAt &&
      now.getTime() - monitoringStartedAt.getTime() >= recoveryStabilityMs
    ) {
      const resolved = await config.database.resolveIncident(
        incident.id,
        `${result.name} has remained operational for five minutes. Resolved.`,
      );
      events.push({
        type: "incident.resolved",
        occurredAt: now,
        incident: resolved,
      });
    }
  }
}

function isCoveredByActiveMaintenance(
  maintenance: Maintenance[],
  monitorName: string,
): boolean {
  return maintenance.some(
    (window) =>
      window.status === "in-progress" && affectsMonitor(window, monitorName),
  );
}

function affectsMonitor(
  value: Pick<Incident | Maintenance, "affectedMonitors">,
  monitorName: string,
): boolean {
  // A global incident/window is represented by an empty affected-monitor list.
  return (
    value.affectedMonitors.length === 0 ||
    value.affectedMonitors.includes(monitorName)
  );
}

function latestUpdateAt(
  incident: Incident,
  status: IncidentStatus,
): Date | undefined {
  return incident.updates.filter((update) => update.status === status).at(-1)
    ?.createdAt;
}

function replaceIncident(incidents: Incident[], replacement: Incident): void {
  const index = incidents.findIndex(
    (incident) => incident.id === replacement.id,
  );
  if (index >= 0) incidents[index] = replacement;
}
